function countVowelsConsonants(s) {
  const vowels = s.match(/[aeiouAEIOU]/g) || [];
  const consonants = s.match(/[bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ]/g) || [];
  return [vowels.length, consonants.length];
}

