function countVowelsConsonants(s) {
  let vowels = 0;
  let consonants = 0;
  const vowelSet = new Set(['a', 'e', 'i', 'o', 'u']);

  for (let i = 0; i < s.length; i++) {
    const char = s[i].toLowerCase();
    if (char >= 'a' && char <= 'z') {
      if (vowelSet.has(char)) {
        vowels++;
      } else {
        consonants++;
      }
    }
  }
  return [vowels, consonants];
}
